// Fills the roadmap's progress bars from data/roadmap.json (generated by scripts/build-site.ts).
// The page reads fine without it: the stages and their descriptions are in the HTML.

async function renderRoadmap() {
  const res = await fetch('data/roadmap.json');
  if (!res.ok) return;
  const phases = await res.json();

  let done = 0;
  let total = 0;
  for (const phase of phases) {
    done += phase.done;
    total += phase.total;
    // Phase names start with their number, e.g. "1 Measurement core".
    const item = document.querySelector(`.roadmap li[data-phase="${parseInt(phase.phase, 10)}"]`);
    if (!item || !phase.total) continue;
    item.querySelector('.progress div').style.width = (phase.done / phase.total) * 100 + '%';
    item.querySelector('.count').textContent = `${phase.done} of ${phase.total} done`;
    item.classList.toggle('done', phase.done === phase.total);
  }
  if (total) document.getElementById('roadmap-total').textContent = `${done} of ${total} milestones are complete so far.`;
}

renderRoadmap().catch(() => {});
